// --- 初始设置 & 全局状态 ---
let spinePlayer = null;
let specialAnimationTimer = null;
let currentSceneIndex = 1; // 1..17
let panelVisible = true;
let positionX = 50; // 0..100
let positionY = 50; // 0..100
let scaleValue = 1.0; // 0.5..1.5
let currentVoiceLang = 'cn'; // 语音语言: cn | jp | en

// DOM 引用
const stage = document.getElementById('stage');
const bgEl = document.getElementById('background');
const playerContainer = document.getElementById('player-container');

// 控制面板元素
const panel = document.getElementById('control-panel');
const btnShowPanel = document.getElementById('show-panel-btn');
const sliderX = document.getElementById('slider-x');
const sliderY = document.getElementById('slider-y');
const sliderScale = document.getElementById('slider-scale');
const valX = document.getElementById('val-x');
const valY = document.getElementById('val-y');
const valScale = document.getElementById('val-scale');
const scenePrev = document.getElementById('scene-prev');
const sceneNext = document.getElementById('scene-next');
const sceneLabel = document.getElementById('scene-label');
const btnStart = document.getElementById('btn-start');
const btnRefresh = document.getElementById('btn-refresh');
const btnSave = document.getElementById('btn-save');
const btnHide = document.getElementById('btn-hide');

// panel初始位置
panel.style.bottom = '';
panel.style.top = '14px';
btnShowPanel.style.bottom = '';
btnShowPanel.style.top = '14px';

// 获取两个音频播放器
const backgroundMusic = document.getElementById('background-music');
const voicePlayer = document.getElementById('voice-player');

// 设置音量
backgroundMusic.volume = 0.8; // 背景音乐音量稍低
voicePlayer.volume = 1.0;   // 语音音量正常

// 动态构建 Interact 语音文件列表
function buildInteractVoices() {
    const base = `./Voices/${currentVoiceLang}`;
    return [1,2,3,4,5,6,7,8].map(i => `${base}/Interact${i}.wav`);
}
let interactVoices = buildInteractVoices();

// --- 封装好的语音播放函数 ---
function playVoice(src) {
    if (voicePlayer) {
        voicePlayer.src = src;
        voicePlayer.play().catch(e => console.error(`Voice play failed for ${src}:`, e));
    }
}

// --- 特殊动作计时器函数 (已更新) ---
function resetSpecialAnimationTimer() {
    if (specialAnimationTimer) {
        clearTimeout(specialAnimationTimer);
    }
    const randomDelay = 30000 + Math.random() * 5000;
    specialAnimationTimer = setTimeout(() => {
        if (spinePlayer) {
            console.log("Playing Special animation due to inactivity.");
            spinePlayer.animationState.setAnimation(0, 'Special', false);
            spinePlayer.animationState.addAnimation(0, 'Idle', true, 0);
            
            // 在此播放 Special 语音
            playVoice(`./Voices/${currentVoiceLang}/Special.wav`);
        }
    }, randomDelay);
}

// --- 初始化Spine Player (已更新) ---
new spine.SpinePlayer("player-container", {
    skelUrl: "dyn_illust_char_172_svrash_ambienceSynesthesia#4.skel",
    atlasUrl: "dyn_illust_char_172_svrash_ambienceSynesthesia#4.atlas",

    rawDataURIs: {
        "dyn_illust_char_172_svrash_ambienceSynesthesia#4.skel": "data:application/skel;base64,",
        "dyn_illust_char_172_svrash_ambienceSynesthesia#4.atlas": "data:application/octet-stream;base64,",
        "dyn_illust_char_172_svrash_ambienceSynesthesia#4.png": "data:image/png;base64,"
    },

    // 其他设置
    alpha: true,
    backgroundColor: "#00000000",
    showControls: false,

    viewport: {
        x: 10,
        y: 560,
        width: 110,
        height: 110,
        padLeft: "675%",
        padRight: "675%",
        padTop: "675%",
        padBottom: "675%"
    },
    
    success: function (player) {
        console.log("Spine assets loaded successfully.");
        spinePlayer = player;
        // 读取配置后再执行启动序列
        if (window.__configLoaded) runStartSequence();
    },

    error: function (player, message) {
        console.error("Spine Player Error:", message);
    }
});

// --- 鼠标点击事件监听 (过滤控制面板) ---
document.addEventListener('click', function (e) {
    if (panel && panel.contains(e.target)) return;
    if (btnShowPanel && btnShowPanel.contains(e.target)) return;

    if (backgroundMusic && backgroundMusic.paused) {
        backgroundMusic.play().catch(e2 => console.error('Music play failed:', e2));
    }
    if (!spinePlayer) return;

    if (voicePlayer && voicePlayer.paused) {
        const randomIndex = Math.floor(Math.random() * interactVoices.length);
        playVoice(interactVoices[randomIndex]);
        spinePlayer.animationState.setAnimation(0, 'Interact', false);
        spinePlayer.animationState.addAnimation(0, 'Idle', true, 0);
    } else {
        console.log('Interact voice busy. Restarting animation only.');
        spinePlayer.animationState.setAnimation(0, 'Interact', false);
        spinePlayer.animationState.addAnimation(0, 'Idle', true, 0);
    }
    resetSpecialAnimationTimer();
});

// --- 页面加载: 读取配置, 同步UI, 自动播放BGM尝试 ---
document.addEventListener('DOMContentLoaded', () => {
    loadConfig().then(() => {
        window.__configLoaded = true;
        applyScene();
        updatePosition();
        syncUI();
        if (!panelVisible) hidePanelImmediate();
        // 若Spine已准备则执行启动序列
        if (spinePlayer) runStartSequence();
        const p = backgroundMusic.play();
        if (p) p.catch(()=>console.warn('BGM autoplay blocked.'));
    });
});

// --- 功能函数 ---
function runStartSequence() {
    if (!spinePlayer) return;
    spinePlayer.animationState.addAnimation(0, 'Idle', true, 0);
    playVoice(`./Voices/${currentVoiceLang}/Start.wav`);
    resetSpecialAnimationTimer();
}

function updatePosition() {
    const offsetX = (positionX - 50) / 50; // -1..1
    const offsetY = (positionY - 50) / 50;
    const maxShiftX = 30; // vw
    const maxShiftY = 24; // vh
    const translateX = offsetX * maxShiftX;
    const translateY = offsetY * maxShiftY;
    
    // 加入缩放
    playerContainer.style.transformOrigin = '50% 50%';
    playerContainer.style.transform = `translate(${translateX}vw, ${translateY}vh) scale(${scaleValue})`;
}

function syncUI() {
    if (sliderX) { sliderX.value = positionX; if (valX) valX.textContent = positionX; }
    if (sliderY) { sliderY.value = positionY; if (valY) valY.textContent = positionY; }
    if (sliderScale) { sliderScale.value = Math.round(scaleValue * 100); if (valScale) valScale.textContent = `${Math.round(scaleValue*100)}%`; }
    if (sceneLabel) sceneLabel.textContent = `${currentSceneIndex} / 17`;
    // 同步语音单选框
    document.querySelectorAll('input[name="voice-lang"]').forEach(r => {
        r.checked = (r.value === currentVoiceLang);
    });
}

function applyScene() {
    bgEl.style.backgroundImage = `url('./Bg/Bg_${currentSceneIndex}.webp')`;
    backgroundMusic.src = `./Bgm/Bgm_${currentSceneIndex}.mp3`;
    backgroundMusic.load();
}
function nextScene() {
    currentSceneIndex++; if (currentSceneIndex > 17) currentSceneIndex = 1;
    applyScene(); resetSpecialAnimationTimer(); backgroundMusic.play(); syncUI();
}
function prevScene() {
    currentSceneIndex--; if (currentSceneIndex < 1) currentSceneIndex = 17;
    applyScene(); resetSpecialAnimationTimer(); backgroundMusic.play(); syncUI();
}

function hidePanelImmediate() { panel.classList.add('hidden'); btnShowPanel.style.display = 'block'; }
function hidePanel() { panelVisible = false; hidePanelImmediate(); }
function showPanel() { panelVisible = true; panel.classList.remove('hidden'); btnShowPanel.style.display = 'none'; }

function showAutoHideAlert(message, duration = 2000) {
    const box = document.getElementById('customAlert');
    box.textContent = message;
    box.style.display = 'block';

    setTimeout(() => {
      box.style.display = 'none';
    }, duration);
}

// --- 配置读取 & 保存 ---
async function loadConfig() {
    try {
        const res = await fetch('./config.json?_=' + Date.now());
        if (!res.ok) throw new Error(res.statusText);
        const cfg = await res.json();
        if (cfg.Bg) currentSceneIndex = parseInt(cfg.Bg, 10) || 1;
        if (cfg.x) positionX = parseInt(cfg.x, 10); else positionX = 50;
        if (cfg.y) positionY = parseInt(cfg.y, 10); else positionY = 50;
        if (cfg.scale) scaleValue = parseInt(cfg.scale, 10) / 100; else scaleValue = 1.0;
        if (typeof cfg.panelVisible === 'boolean') panelVisible = cfg.panelVisible; else panelVisible = true;
        if (cfg.voice) currentVoiceLang = cfg.voice; else currentVoiceLang = 'cn';
        interactVoices = buildInteractVoices();

        // 读取 UI control (top|bottom) 并更新显示及定位
        const placeIndicator = document.getElementById('place-indicator');
        if (cfg['UI control'] === 'bottom') {
            // 修改控制面板与显示按钮的位置为 bottom:14px
            if (panel) {
                panel.style.top = '';
                panel.style.bottom = '14px';
            }
            if (btnShowPanel) {
                btnShowPanel.style.top = '';
                btnShowPanel.style.bottom = '14px';
            }
            if (placeIndicator) placeIndicator.textContent = 'UI control: bottom';
        } else {
            // 默认为 top
            if (panel) {
                panel.style.bottom = '';
                panel.style.top = '14px';
            }
            if (btnShowPanel) {
                btnShowPanel.style.bottom = '';
                btnShowPanel.style.top = '14px';
            }
            if (placeIndicator) placeIndicator.textContent = 'UI control: top';
        }
    } catch (e) {
        console.warn('读取配置失败，使用默认值', e);
    }
}

// --- 事件绑定 ---
if (sliderX) sliderX.addEventListener('input', e => { positionX = parseInt(e.target.value, 10); updatePosition(); if (valX) valX.textContent = positionX; });
if (sliderY) sliderY.addEventListener('input', e => { positionY = parseInt(e.target.value, 10); updatePosition(); if (valY) valY.textContent = positionY; });
if (sliderScale) sliderScale.addEventListener('input', e => {
    scaleValue = parseInt(e.target.value, 10) / 100;
    if (valScale) valScale.textContent = `${e.target.value}%`;
    updatePosition();
});
if (sceneNext) sceneNext.addEventListener('click', e => { e.stopPropagation(); nextScene(); });
if (scenePrev) scenePrev.addEventListener('click', e => { e.stopPropagation(); prevScene(); });
if (btnStart) btnStart.addEventListener('click', e => { e.stopPropagation(); runStartSequence(); });
if (btnRefresh) btnRefresh.addEventListener('click', e => {
    loadConfig().then(() => {
        window.__configLoaded = true;
        applyScene();
        updatePosition();
        syncUI();
        if (!panelVisible) hidePanelImmediate();
        // 若Spine已准备则执行启动序列
        if (spinePlayer) runStartSequence();
        const p = backgroundMusic.play();
        if (p) p.catch(()=>console.warn('BGM autoplay blocked.'));
    });
});
if (btnSave) {
    btnSave.addEventListener('click', e => {
        // 此处不使用alert，因为在wallpaper engine中会卡住。
        showAutoHideAlert("要保存配置, 请在Wallpaper Engine页面:\n\n右键此壁纸 -> 在资源管理器中打开 ->\n右键文件夹中“config.json” -> 在记事本中编辑。\n\n不便之处, 敬请谅解。\n此弹窗将在10秒后自动关闭。", 10000);
    });
};
if (btnHide) btnHide.addEventListener('click', e => { e.stopPropagation(); hidePanel(); });
if (btnShowPanel) btnShowPanel.addEventListener('click', e => { e.stopPropagation(); showPanel(); });

if (panel) { panel.addEventListener('mousedown', e => e.stopPropagation()); panel.addEventListener('click', e => e.stopPropagation()); }

// 语音语言切换事件
document.querySelectorAll('input[name="voice-lang"]').forEach(radio => {
    radio.addEventListener('change', e => {
        if (!e.target.checked) return;
        const newLang = e.target.value;
        if (newLang === currentVoiceLang) return;
        currentVoiceLang = newLang;
        interactVoices = buildInteractVoices();
        playVoice(`./Voices/${currentVoiceLang}/Start.wav`);
        resetSpecialAnimationTimer();
    });
});

// 失焦/聚焦处理特殊动画计时器
window.addEventListener('blur', () => { if (specialAnimationTimer) { clearTimeout(specialAnimationTimer); specialAnimationTimer = null; } });
window.addEventListener('focus', () => resetSpecialAnimationTimer());
